import React, { useEffect, useState, useCallback } from "react";
import { Link } from "react-router-dom";
import Navbar from "../components/Navbar";
import { dashboardAPI, hospitalAPI } from "../services/api";

export default function PatientDashboard() {
  const [data, setData] = useState(null);
  const [hospitals, setHospitals] = useState([]);
  const [loadingHosp, setLoadingHosp] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    dashboardAPI.get()
      .then(({ data }) => setData(data))
      .catch(() => setError("Failed to load dashboard"));
  }, []);

  const findHospitals = useCallback(() => {
    setLoadingHosp(true);
    navigator.geolocation.getCurrentPosition(
      async ({ coords }) => {
        try {
          const { data } = await hospitalAPI.nearby(coords.latitude, coords.longitude);
          setHospitals(data);
        } catch {
          setError("Could not fetch hospitals");
        } finally {
          setLoadingHosp(false);
        }
      },
      () => { setError("Location access denied."); setLoadingHosp(false); }
    );
  }, []);

  if (error) return <div className="page"><Navbar /><div className="container main-content"><div className="alert alert-error">{error}</div></div></div>;
  if (!data) return <div className="loading-screen"><span className="spinner"></span></div>;

  const { user, latestRecord, history, doctors } = data;

  return (
    <div className="page">
      <Navbar />
      <main className="container main-content">
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1.5rem" }}>
          <div>
            <h1 style={{ fontSize: "1.5rem", fontWeight: 700 }}>Welcome, {user.name} 👋</h1>
            <p style={{ color: "var(--text-muted)", fontSize: ".9rem" }}>Patient Dashboard</p>
          </div>
          <Link to="/patient/predict" className="btn btn-primary">+ New Assessment</Link>
        </div>

        {/* Latest Result */}
        {latestRecord && (
          <div className="card" style={{ marginBottom: "1.5rem" }}>
            <h3 className="card-title">Latest Assessment</h3>
            <div style={{ display: "flex", gap: "2rem", alignItems: "center", flexWrap: "wrap" }}>
              <div>
                <div style={{ fontSize: ".8rem", color: "var(--text-muted)" }}>Result</div>
                <span className={`badge ${latestRecord.predictionResult === "Likely" ? "badge-danger" : "badge-success"}`} style={{ fontSize: "1rem", padding: ".3rem .8rem" }}>
                  {latestRecord.predictionResult}
                </span>
              </div>
              <div>
                <div style={{ fontSize: ".8rem", color: "var(--text-muted)" }}>Risk Probability</div>
                <strong style={{ fontSize: "1.4rem" }}>{latestRecord.riskProbability}%</strong>
              </div>
              <div>
                <div style={{ fontSize: ".8rem", color: "var(--text-muted)" }}>Date</div>
                <span>{new Date(latestRecord.createdAt).toLocaleDateString()}</span>
              </div>
              <Link to="/patient/history" className="btn btn-outline btn-sm" style={{ marginLeft: "auto" }}>Full History</Link>
            </div>
          </div>
        )}

        <div className="grid-2" style={{ marginBottom: "1.5rem" }}>
          {/* Recent History */}
          <div className="card">
            <h3 className="card-title">Recent Assessments</h3>
            {history.length === 0 ? (
              <p style={{ color: "var(--text-muted)", fontSize: ".9rem" }}>No assessments yet. <Link to="/patient/predict">Take your first one →</Link></p>
            ) : (
              <div className="table-wrap">
                <table>
                  <thead><tr><th>Date</th><th>Result</th><th>Risk %</th></tr></thead>
                  <tbody>
                    {history.map((r) => (
                      <tr key={r._id}>
                        <td>{new Date(r.createdAt).toLocaleDateString()}</td>
                        <td><span className={`badge ${r.predictionResult === "Likely" ? "badge-danger" : "badge-success"}`}>{r.predictionResult}</span></td>
                        <td>{r.riskProbability}%</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {/* Doctors */}
          <div className="card">
            <h3 className="card-title">Available Doctors</h3>
            {doctors.filter(d => d.isAvailable).slice(0, 4).map((d) => (
              <div key={d._id} className="doctor-card" style={{ marginBottom: "1rem" }}>
                <div className="doctor-avatar">{d.name[0].toUpperCase()}</div>
                <div className="doctor-info">
                  <h4>{d.name}</h4>
                  <p className="doctor-meta">{d.specialization || "General Physician"}</p>
                  <span className="badge badge-success">● Online</span>
                </div>
              </div>
            ))}
            {doctors.filter(d => d.isAvailable).length === 0 && <p style={{ color: "var(--text-muted)", fontSize: ".9rem" }}>No doctors online right now.</p>}
            <Link to="/doctors" className="btn btn-outline btn-sm" style={{ marginTop: ".5rem" }}>View All Doctors</Link>
          </div>
        </div>

        {/* Nearby Hospitals */}
        <div className="card">
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1rem" }}>
            <h3 className="card-title" style={{ margin: 0 }}>Nearby Hospitals</h3>
            <button className="btn btn-outline btn-sm" onClick={findHospitals} disabled={loadingHosp}>
              {loadingHosp ? <><span className="spinner"></span> Searching…</> : "📍 Find Near Me"}
            </button>
          </div>
          {hospitals.length > 0 ? (
            <div className="table-wrap">
              <table>
                <thead><tr><th>Hospital</th><th>Address</th><th>Distance (km)</th></tr></thead>
                <tbody>
                  {hospitals.map((h, i) => (
                    <tr key={i}><td>{h.name}</td><td>{h.address}</td><td>{h.distance} km</td></tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <p style={{ color: "var(--text-muted)", fontSize: ".9rem" }}>Click "Find Near Me" to locate hospitals in your area.</p>
          )}
        </div>
      </main>
    </div>
  );
}
